{
  "title": "Al-Yamamah Digital Services Privacy Policy",
  "planted": [
    {
      "slot": "p1",
      "text": "Personal data may be stored or transferred to any foreign jurisdiction selected by our cloud infrastructure vendor, without prior notice to the user and without conducting any preliminary adequacy assessments or implementing additional cross-border safeguards."
    },
    {
      "slot": "p2",
      "text": "We collect only the specific data fields strictly necessary for the fulfillment of the requested digital service, which comprise your full legal name, active email address, and verified telephone number."
    },
    {
      "slot": "p3",
      "text": "Collected personal data shall be utilized exclusively for the specific operational objectives for which it was originally gathered, except in those limited circumstances where prior written authorization has been obtained from the user."
    }
  ],
  "neutral": [
    "All service fees are billed in Saudi Riyals on a recurring monthly basis and must be settled within fifteen days of the invoice date.",
    "This agreement shall commence upon successful account activation and shall remain in full force until terminated by either party with thirty days written notice.",
    "The total aggregate liability of the company for any direct claims arising out of or related to the platform shall not exceed the total fees paid by the user during the preceding three months.",
    "This agreement shall be governed by and construed in accordance with the substantive laws applicable within the Kingdom of Saudi Arabia, excluding its conflict of laws principles.",
    "All software, user interfaces, trademarks, and proprietary documentation made available through the service remain the exclusive intellectual property of the company and its licensors."
  ]
}
